import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Run, Step } from '../types'
import { H, rowSvg } from './draw'
import type { Bar } from './draw'

const run = atom({ plugin: 'pixel-progress', key: 'run' } as const, null)
const isHidden = atom({ plugin: 'pixel-progress', key: 'isHidden' } as const, false)
const now = atom({ plugin: 'pixel-progress', key: 'now' } as const, 0)
// The session's colour, kept with the session so a plugin reload, /clear or a resume keeps it.
const sessionColor = atom({ plugin: 'pixel-progress', key: 'color' } as const, '')
// Seconds each finished request of this session took: the estimate for a request with no step list.
const history = atom({ plugin: 'pixel-progress', key: 'history' } as const, [])

// The colour of the outline, the dot, the dithered boxes and the pill while ready or
// working: picked once when a session is created and kept for that session only.
// No green or red: green is kept for done, red for something gone wrong.
export const ACCENTS = ['#8f8cf4', '#e0699a', '#3fa7d6', '#f08a4b', '#c678dd', '#e5b84b', '#5b8def']
/** Done: the whole bar, outline included, turns green. */
export const DONE = '#5fbf8f'
/** An error, a refusal or a stopped request: the whole bar turns red. */
export const ERROR = '#e5484d'

const BAR = 16
const MAX_STEPS = 100
const MAX_TITLE = 48

const PLAN_TOOL = 'mcp__ccd_turn__update_plan'
const WRAP_TOOL = 'mcp__ccd_turn__wrap_up'

type StepInput = {
  items?: { content?: unknown; status?: unknown }[]
  todos?: { content?: unknown; status?: unknown }[]
  advance?: boolean
  done?: number[]
  start?: number
}

// ---------------------------------------------------------------------------
// Pure helpers: the step list, the estimate and what the bar shows.

const stepsOf = (raw: StepInput['items']): Step[] =>
  (raw ?? []).slice(0, MAX_STEPS).map(s => ({ content: String(s.content ?? '').trim(), status: String(s.status ?? 'pending') }))

/**
 * The step list after one tool call: the desktop's step list (update_plan, its
 * advance/done/start shorthands, wrap_up ticking it off) or the terminal's
 * TodoWrite. Null when the call does not touch a step list.
 */
export function applySteps(prev: Step[], tool: string, input: StepInput): Step[] | null {
  let list: Step[]
  if (tool === 'TodoWrite' && Array.isArray(input.todos)) {
    list = stepsOf(input.todos)
  } else if (tool === PLAN_TOOL) {
    list = Array.isArray(input.items) ? stepsOf(input.items) : prev.map(s => ({ ...s }))
    if (input.advance) {
      const at = list.findIndex(s => s.status === 'in_progress')
      if (at >= 0) list[at]!.status = 'completed'
      const nextAt = list.findIndex(s => s.status === 'pending')
      if (nextAt >= 0) list[nextAt]!.status = 'in_progress'
    }
    for (const n of Array.isArray(input.done) ? input.done : []) if (list[n - 1]) list[n - 1]!.status = 'completed'
    if (typeof input.start === 'number' && list[input.start - 1]) list[input.start - 1]!.status = 'in_progress'
  } else if (tool === WRAP_TOOL && prev.length > 0) {
    list = prev.map(s => ({ ...s, status: 'completed' }))
  } else {
    return null
  }
  return list.length > 0 ? list : null
}

const doneOf = (steps: Step[]): number => steps.filter(s => s.status === 'completed').length

/** The run after its step list changed at `at` (ms): finished steps add their time to the estimate. */
export function withSteps(r: Run, steps: Step[], at: number): Run {
  const gained = doneOf(steps) - doneOf(r.steps)
  if (gained <= 0) return { ...r, steps }
  const each = Math.max(0, (at - r.stepMarkAt) / 1000 / gained)
  return { ...r, steps, stepMarkAt: at, durations: [...r.durations, ...Array<number>(gained).fill(each)].slice(-50) }
}

/**
 * Seconds left, from the average finished step times the steps still to go,
 * less what the current step has already used. Null until a step has finished.
 */
export function secondsLeft(r: Run, at: number): number | null {
  const left = r.steps.length - doneOf(r.steps)
  if (left <= 0 || r.durations.length === 0) return null
  const avg = r.durations.reduce((a, b) => a + b, 0) / r.durations.length
  const used = Math.min(avg, Math.max(0, (at - r.stepMarkAt) / 1000))
  return Math.max(0, Math.round(avg * left - used))
}

/**
 * Seconds left for a request with no step list: the average of this session's
 * finished requests, less the time this one has run so far. Null with no history yet.
 */
export function historyLeft(r: Run, at: number, past: number[]): number | null {
  if (past.length === 0) return null
  const avg = past.reduce((a, b) => a + b, 0) / past.length
  return Math.max(0, Math.round(avg - (at - r.startedAt) / 1000))
}

/** Time left, short: "~3 min left", "<1 min left", "almost done", or "estimating…" with nothing to go on yet. */
export const leftText = (s: number | null): string =>
  s === null ? 'estimating…' : s < 15 ? 'almost done' : s < 60 ? '<1 min left' : `~${Math.round(s / 60)} min left`

const clip = (s: string, max: number): string => (s.length > max ? s.slice(0, max - 1) + '…' : s)

export type Status = 'ready' | 'working' | 'done' | 'error' | 'stopped'

/** What the bar shows: its state, the drawing's input, and the text right of the bar (time left, never time taken). */
export type View = { status: Status; bar: Bar; right: string }

/** The bar for a run (null: the session's resting bar) at `at` ms, given this session's finished request times. */
export function viewOf(r: Run | null, at: number, past: number[] = []): View {
  if (r === null) {
    return { status: 'ready', bar: { title: 'Claude', total: 0, done: 0, running: 0, isFinished: false, label: 'Ready' }, right: 'ready' }
  }
  const total = r.steps.length
  const done = doneOf(r.steps)
  const percent = Math.round(100 * Math.max(0, Math.min(1, r.shown)))
  const base = { total, done, running: 0, progress: r.shown }

  if (r.outcome === 'done') return { status: 'done', bar: { ...base, title: 'Done', isFinished: true, label: 'Done' }, right: '100% · done' }
  if (r.outcome === 'error') {
    return { status: 'error', bar: { ...base, title: 'Error', isFinished: false, label: 'Error' }, right: `${percent}% · error` }
  }
  if (r.outcome === 'stopped') {
    return { status: 'stopped', bar: { ...base, title: 'Stopped', isFinished: false, label: 'Stopped' }, right: `${percent}% · stopped` }
  }

  const current = r.steps.find(s => s.status === 'in_progress') ?? r.steps.find(s => s.status !== 'completed')
  const left = total ? secondsLeft(r, at) : historyLeft(r, at, past)
  return {
    status: 'working',
    bar: {
      ...base,
      running: Math.min(1, total - done),
      title: clip(current?.content || 'Working', MAX_TITLE),
      isFinished: false,
      label: total ? `Tasks ${done}/${total}` : 'Working',
    },
    right: `${percent}% · ${leftText(left)}`,
  }
}

/**
 * Where the fill should be now (0..1), moving between step ticks instead of jumping:
 * the finished steps plus how far into the current one it should be by the time
 * steps usually take (never past 90% of it until it is ticked). Before any step has
 * finished, and for a request with no steps, it creeps forward on a slowing curve,
 * or by this session's earlier requests when there are some.
 */
export function targetOf(r: Run, at: number, past: number[] = []): number {
  if (r.outcome === 'done') return 1
  const total = r.steps.length
  const creep = (secs: number, typical: number | null) =>
    typical ? Math.min(0.95, secs / typical) : (0.9 * secs) / (secs + 45)
  if (total === 0) {
    const typical = past.length ? past.reduce((a, b) => a + b, 0) / past.length : null
    return creep(Math.max(0, (at - r.startedAt) / 1000), typical)
  }
  const done = doneOf(r.steps)
  if (done >= total) return 1
  const avg = r.durations.length ? r.durations.reduce((a, b) => a + b, 0) / r.durations.length : null
  const inStep = Math.max(0, (at - r.stepMarkAt) / 1000)
  const part = avg ? Math.min(0.9, inStep / avg) : (0.9 * inStep) / (inStep + 45)
  return (done + part) / total
}

/** One easing step of the shown fill toward its target: a third of the way each tick. */
export const easeToward = (shown: number, target: number): number =>
  Math.abs(target - shown) < 0.002 ? target : shown + (target - shown) * 0.35

/** The colour of the outline, dot, pixels and pill for a state. */
export const colorOf = (status: Status, accent: string): string =>
  status === 'done' ? DONE : status === 'error' || status === 'stopped' ? ERROR : accent

/** The terminal's text bar for a view. */
export function textBar(v: View): string {
  const filled = v.status === 'done' ? BAR : Math.round(BAR * Math.max(0, Math.min(1, v.bar.progress ?? 0)))
  return '█'.repeat(filled) + '░'.repeat(BAR - filled)
}

export const newRun = (at: number): Run => ({
  startedAt: at,
  endedAt: null,
  outcome: null,
  steps: [],
  shown: 0,
  stepMarkAt: at,
  durations: [],
  tools: 0,
})

// ---------------------------------------------------------------------------
// Engine work: each takes $ and is declared here, as the engine requires.

async function startRun($: EngineInterface): Promise<void> {
  const at = await $.clock.now()
  await update($, run, () => newRun(at))
  await update($, now, () => at)
}

async function resetIfFinished($: EngineInterface): Promise<void> {
  const r = await read($, run)
  if (r === null || r.endedAt !== null) await startRun($)
}

async function seeTool($: EngineInterface, tool: string, input: StepInput): Promise<void> {
  const at = await $.clock.now()
  await update($, run, r => {
    if (r === null || r.endedAt !== null) return r
    const steps = applySteps(r.steps, tool, input)
    const counted = { ...r, tools: r.tools + 1 }
    return steps ? withSteps(counted, steps, at) : counted
  })
  await update($, now, () => at)
}

async function endRun($: EngineInterface, reason: string): Promise<void> {
  const at = await $.clock.now()
  const r = await read($, run)
  if (r === null || r.endedAt !== null) return
  const outcome: Run['outcome'] = reason === 'answer' ? 'done' : reason === 'aborted' ? 'stopped' : 'error'
  await update($, run, () => ({ ...r, endedAt: at, outcome, shown: outcome === 'done' ? 1 : r.shown }))
  if (outcome === 'done') await update($, history, list => [...list, (at - r.startedAt) / 1000].slice(-20))
  await update($, now, () => at)
}

async function tick($: EngineInterface): Promise<void> {
  const r = await read($, run)
  if (r === null || r.endedAt !== null) return
  const at = await $.clock.now()
  const target = targetOf(r, at, await read($, history))
  await update($, run, cur => (cur === null || cur.endedAt !== null ? cur : { ...cur, shown: easeToward(cur.shown, target) }))
  await update($, now, () => at)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    if (!(await read($, sessionColor))) {
      const picked = ACCENTS[Math.floor(Math.random() * ACCENTS.length)] ?? ACCENTS[0]!
      await update($, sessionColor, () => picked)
    }
    await $.command.register({ name: 'progress', description: 'Show or hide the task progress bar above the prompt' })
    // Moves the fill and redraws the time left a few times a second while a request runs.
    $.clock.every(400, () => void tick($))
    return started
  })

  on('command.run', { command: 'progress' }, async $ => {
    const wasHidden = await read($, isHidden)
    await update($, isHidden, () => !wasHidden)
    return { text: wasHidden ? 'Progress bar shown.' : 'Progress bar hidden. /progress shows it again.' }
  })

  // A new prompt resets the bar: the last request's "Done · 100%" never carries over.
  on('prompt.submit', async ($, e, next) => {
    await startRun($)
    return next(e)
  }).catch(($, e, next) => next(e))

  // Backup for prompts that reach the session another way (the desktop app, the
  // SDK): a turn that starts after the last one finished resets the bar too.
  on('turn.start', async ($, e, next) => {
    await resetIfFinished($)
    return next(e)
  }).catch(($, e, next) => next(e))

  // Only the main session's own calls: a subagent's steps are not this request's.
  on('tool.call', async ($, e, next) => {
    if (!e.agentId) await seeTool($, e.tool, e as unknown as StepInput)
    return next(e)
  }).catch(($, e, next) => next(e))

  on('turn.complete', async ($, e, next) => {
    if (!e.agentId) await endRun($, e.reason)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)
    const r = await read($, run)

    // Other mods' bands (savvy-progress) still draw, beneath this row. The
    // engine's own placeholder is never nested: the desktop drops a band that nests it.
    const drawn = await Promise.resolve(next(e)).catch(() => null)
    const below = drawn && typeof drawn === 'object' && (drawn as { type?: string }).type !== 'engine' ? drawn : null

    const at = Math.max(await read($, now), r?.startedAt ?? 0)
    const view = viewOf(r, at, await read($, history))
    const { bar, right } = view
    // One colour for the outline, dot, pixels and pill: green when done, red when
    // something went wrong, the session's colour otherwise.
    const color = colorOf(view.status, (await read($, sessionColor)) || ACCENTS[0]!)
    const ui = $.ui.resolve(e)
    const { Box, Text, Button } = ui
    const dismiss = (
      <Button key="pixel-progress-dismiss" label="✕" plain role="dismiss" onPress={() => update($, isHidden, () => true)} />
    )

    // Desktop: savvy-progress's drawing, in a rounded outline of the state's colour.
    if (e.surface !== 'terminal' && 'Svg' in ui) {
      const { Svg } = ui
      const width = Math.max(180, Math.min(1600, (e.props.bodyColumns || 100) * 8 - 80))
      return (
        <Box flexDirection="column">
          <Box borderStyle="round" borderColor={color} paddingX={1} flexDirection="row" alignItems="center" gap={1}>
            <Svg
              source={rowSvg(bar, width, view.status === 'working', color, right)}
              alt={`${bar.title}: ${bar.label}, ${right}`}
              width={width}
              height={H}
            />
            {dismiss}
          </Box>
          {below}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box borderStyle="round" borderColor={color} paddingX={1} flexDirection="row">
          <Text wrap="truncate-end">
            <Text color={color}>● </Text>
            <Text bold>{bar.title} </Text>
            <Text color={color}>{textBar(view)}</Text>
            <Text dimColor>
              {' '}
              {bar.label} · {right}
            </Text>
          </Text>
          {dismiss}
        </Box>
        {below}
      </Box>
    )
  })
}

