/** One step of a task's step list, as the step tools report it. */
export type Step = { content: string; status: string }

/** The request in progress (or the last one), as the bar draws it. */
export type Run = {
  startedAt: number
  /** Set when the turn ends. */
  endedAt: number | null
  /** How the request ended: shown green (done) or red (error, stopped). */
  outcome: "done" | "error" | "stopped" | null
  steps: Step[]
  /** The fill shown (0..1): eased toward the estimate a few times a second, so the bar moves smoothly. */
  shown: number
  /** When the last step finished, or the run started. */
  stepMarkAt: number
  /** Seconds each finished step took, for the time-left estimate. */
  durations: number[]
  tools: number
}

declare module 'claude-code' {
  interface PluginState {
    'pixel-progress': { run: Run | null; isHidden: boolean; now: number; color: string; history: number[] }
  }
}
